namespace Fanex.Age.UI.TotalBets
{
    public partial class HDPOU_Page : TotalBets_Page
    {
        #region Variable
        private string rowBgOdd = Fanex.Age.UI.Common.RowBgOdd;
        private string rowBgEven = Fanex.Age.UI.Common.RowBgEven;
        private string rowBgLive = Fanex.Age.UI.Common.RowBgLive;
        #endregion

        #region Override

        public override void RenderContent(HtmlTextWriter writer)
        {
            var darkModeName = DarkModeHelper.GetDarkModeName(CurrentUserSession);
            if (!string.IsNullOrWhiteSpace(darkModeName))
            {
                rowBgOdd = DarkModeColor.RowBgOdd;
                rowBgEven = DarkModeColor.RowBgEven;
                rowBgLive = DarkModeColor.RowBgLive;
            }

            DataTable hdpOUList = View as DataTable;
            HDPOU_Template tpl = new HDPOU_Template();
            tpl.DarkModeName = darkModeName;

            tpl.Contents.LeagueContents.Clear();
            if (hdpOUList.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                // Render league content
                int currentLeagueId = 0;
                int matchIndex = 0;

                HDPOU_Contents_LeagueContents_Block leagueBlock = new HDPOU_Contents_LeagueContents_Block();
                HDPOU_Contents_LeagueContents_MatchContents_Block matchBlock = new HDPOU_Contents_LeagueContents_MatchContents_Block();

                for (int i = 0; i < hdpOUList.Rows.Count; i++)
                {
                    DataRow dr = hdpOUList.Rows[i];

                    int leagueId = Convert.ToInt32(dr["leagueid"]);
                    int leagueGroupId = Convert.ToInt32(dr["leaguegroupid"]);

                    if (i == 0 || currentLeagueId != leagueId)
                    {
                        // New league, ignore first row
                        if (i != 0) tpl.Contents.LeagueContents.Append(leagueBlock);

                        matchIndex = 1;
                        currentLeagueId = leagueId;

                        leagueBlock.MatchContents.Clear();
                        leagueBlock.LeagueName = AppSettings.IsSiteLabel777 ? 
                            CacheRef.GetLeagueName(leagueId, leagueGroupId):
                            CacheRef.GetLeagueName(leagueId);
                    }
                    else
                    {
                        matchIndex++;
                    }

                    RenderMatchRow(matchBlock, dr, matchIndex, i + 1);

                    leagueBlock.MatchContents.Append(matchBlock);
                }

                if (leagueBlock != null) tpl.Contents.LeagueContents.Append(leagueBlock);
            }

            // Bet List Url
            tpl.BetListsUrl.BetListsUrl = BetlistHelper.MapBetlistsDomain();
            tpl.level = LevelName(UserSession.Current.RoleId);

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }
        }

        private string LevelName(byte roleId)
        {
            return roleId == 4 ? "super" :
                roleId == 3 ? "master" :
                "agent";
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            if (!CurrentUserSession.SubPageAccess.ViewTotalBets)
            {
                return new ErrorPage_Page(Resources.Lang.strNotAccessPage);
            }

            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetHDPOU();
        }
        #endregion

        #region Utility

        /// <summary>
        /// Render match row
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        /// <param name="matchIndex"></param>
        /// <param name="rowIndex"></param>
        private void RenderMatchRow(HDPOU_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr, int matchIndex, int rowIndex)
        {
            // Render match content
            if (Convert.ToInt16(dr["liveindicator"]) == 1)
            {
                matchBlock.ColorClass = rowBgLive;
                matchBlock.TimeValue = dr["livehomescore"] + " - " + dr["liveawayscore"];
                matchBlock.LiveNotice.Show();
            }
            else
            {
                matchBlock.ColorClass = (matchIndex % 2) == 0 ? rowBgEven : rowBgOdd;
                matchBlock.TimeValue = dr["showtime"].ToString();
                matchBlock.LiveNotice.Hide();
            }
            matchBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;
            matchBlock.Home = CacheRef.GetTeamName(Convert.ToInt32(dr["homeid"])) + (Convert.ToBoolean(dr["isNeutral"]) ? Resources.Lang.IsNeutral : string.Empty);
            matchBlock.Away = CacheRef.GetTeamName(Convert.ToInt32(dr["awayid"]));
            matchBlock.No = rowIndex.ToString();

            // Render value column
            RenderHandicapTotal(matchBlock, dr);
            RenderOverUnderTotal(matchBlock, dr);
            RenderHandicapFirstHalf(matchBlock, dr);
            RenderOverUnderFirstHalf(matchBlock, dr);
        }

        /// <summary>
        /// Render handicap total column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderHandicapTotal(HDPOU_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            //Handicap Total
            if (Convert.ToInt16(dr["betcount_hdp"]) != 0)
            {
                decimal HdpTotal = Convert.ToDecimal(dr["home_odds_HDP"]) - Convert.ToDecimal(dr["away_odds_HDP"]);
                matchBlock.HandicapTotalValue.HandicapTotalValue = NegativeNumberRoundColor(HdpTotal);
                matchBlock.HandicapTotalValue.MatchId = dr["matchid"].ToString();
                matchBlock.HandicapTotalButton.MatchId = dr["matchid"].ToString();

                matchBlock.HandicapTotalValue.Show();
                matchBlock.HandicapTotalButton.Show();
            }
            else
            {
                matchBlock.HandicapTotalValue.Hide();
                matchBlock.HandicapTotalButton.Hide();
            }
        }

        /// <summary>
        /// Render over under total column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderOverUnderTotal(HDPOU_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            //Over Under Total
            if (Convert.ToInt16(dr["betcount_ou"]) != 0)
            {
                decimal OUTotal = Convert.ToDecimal(dr["home_odds_OU"]) - Convert.ToDecimal(dr["away_odds_OU"]);

                matchBlock.OverUnderTotalValue.OverUnderTotalValue = NegativeNumberRoundColor(OUTotal);
                matchBlock.OverUnderTotalValue.MatchId = dr["matchid"].ToString();
                matchBlock.OverUnderTotalButton.MatchId = dr["matchid"].ToString();

                matchBlock.OverUnderTotalValue.Show();
                matchBlock.OverUnderTotalButton.Show();
            }
            else
            {
                matchBlock.OverUnderTotalValue.Hide();
                matchBlock.OverUnderTotalButton.Hide();
            }
        }
        /// <summary>
        /// Render handicap first half column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderHandicapFirstHalf(HDPOU_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            // First half HDP 
            if (Convert.ToInt16(dr["BetCount_HTHDP"]) != 0)
            {
                decimal HdpFH = Convert.ToDecimal(dr["home_odds_HTHDP"]) - Convert.ToDecimal(dr["away_odds_HTHDP"]);

                matchBlock.HandicapFirstHalfValue.HandicapFirstHalfValue = NegativeNumberRoundColor(HdpFH);
                matchBlock.HandicapFirstHalfValue.MatchId = dr["matchid"].ToString();
                matchBlock.HandicapFirstHalfButton.MatchId = dr["matchid"].ToString();

                matchBlock.HandicapFirstHalfValue.Show();
                matchBlock.HandicapFirstHalfButton.Show();
            }
            else
            {
                matchBlock.HandicapFirstHalfValue.Hide();
                matchBlock.HandicapFirstHalfButton.Hide();
            }
        }
        /// <summary>
        /// Render over under first half column
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        private void RenderOverUnderFirstHalf(HDPOU_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr)
        {
            // First half OU
            if (Convert.ToInt16(dr["BetCount_HTOU"]) != 0)
            {
                decimal OUHT = Convert.ToDecimal(dr["home_odds_HTOU"]) - Convert.ToDecimal(dr["away_odds_HTOU"]);

                matchBlock.OverUnderFirstHalfValue.OverUnderFirstHalfValue = NegativeNumberRoundColor(OUHT);
                matchBlock.OverUnderFirstHalfValue.MatchId = dr["matchid"].ToString();
                matchBlock.OverUnderFirstHalfButton.MatchId = dr["matchid"].ToString();

                matchBlock.OverUnderFirstHalfValue.Show();
                matchBlock.OverUnderFirstHalfButton.Show();
            }
            else
            {
                matchBlock.OverUnderFirstHalfValue.Hide();
                matchBlock.OverUnderFirstHalfButton.Hide();
            }
        }
        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private static string NegativeNumberRoundColor(object number)
        {
            decimal num = Convert.ToDecimal(number);

            return num < 0 ? "<font color='#eb6003'>" + Formater.DecFormat(num, 0) + "</font>" : Formater.DecFormat(num, 0);

        }
        #endregion
    }
}
